function App() {
  return <MoonStoreProvider><Toaster position="bottom-right" richColors /><Switch>
    <Route path="/" component={Home} />
    <Route path="/login" component={Login} />
    <Route path="/register" component={Register} />
    <Route path="/forgot-password" component={ForgotPassword} />
    <Route path="/onboarding" component={Onboarding} />
    <Route path="/checkout/success/:orderId" component={PurchaseSuccess} />
    <Route path="/download/:orderId" component={DownloadPage} />
    <Route path="/dashboard/products/new" component={ProductEditor} />
    <Route path="/dashboard/products/:id" component={ProductEditor} />
    <Route path="/dashboard/orders/:id" component={OrderDetail} />
    <Route path="/dashboard/customers/:id" component={CustomerDetail} />
    <Route path="/dashboard" component={Dashboard} />
    <Route path="/dashboard/store" component={StoreBuilder} />
    <Route path="/dashboard/products" component={Products} />
    <Route path="/dashboard/orders" component={Orders} />
    <Route path="/dashboard/customers" component={Customers} />
    <Route path="/dashboard/analytics" component={Analytics} />
    <Route path="/dashboard/coupons" component={Coupons} />
    <Route path="/dashboard/marketing" component={() => <ComingSoon title="Marketing, made more intentional" icon={Sparkles} copy="Email campaigns, customer segments, and WhatsApp marketing are in the MoonStore roadmap. When they arrive, they’ll be connected to the same customer data you own here." />} />
    <Route path="/dashboard/automations" component={() => <ComingSoon title="Automations that feel human" icon={Zap} copy="Set up purchase follow-ups, delivery notifications, and abandoned checkout journeys when the automation layer is ready. Nothing here pretends to run today." />} />
    <Route path="/dashboard/settings" component={SettingsPage} />
    <Route path="/dashboard/help" component={HelpPage} />
    <Route path="/:username/:productSlug/checkout" component={Checkout} />
    <Route path="/:username/:productSlug" component={ProductPage} />
    <Route path="/:username" component={PublicStore} />
    <Route path="/404" component={() => <NotFound title="That page drifted away" copy="The route you followed doesn’t exist in this demo workspace." />} />
    <Route component={() => <NotFound title="This page doesn’t exist" copy="Try heading back to the MoonStore dashboard or exploring the demo store." />} />
  </Switch></MoonStoreProvider>;
}

