      <section className="landing-cta px-5 py-14 sm:px-8 lg:px-16"><div className="mx-auto grid max-w-[1240px] items-center gap-10 overflow-hidden rounded-[30px] bg-[#171735] px-7 py-10 text-white shadow-[0_24px_70px_rgba(28,29,62,.16)] sm:px-12 lg:grid-cols-[1.05fr_.95fr] lg:px-14 lg:py-14"><div><div className="eyebrow text-[#b8b3ff]">Your next chapter starts here</div><h2 className="mt-4 max-w-[560px] font-display text-[40px] font-semibold leading-[1.02] tracking-[-.06em] sm:text-[58px]">Make space for the work that matters.</h2><p className="mt-5 max-w-[460px] text-[14px] leading-6 text-white/65">One storefront, one customer relationship, and one calm place to build what people come back for.</p><div className="mt-7 flex flex-wrap gap-3"><PillButton href="/register" icon={ArrowRight}>Start selling free</PillButton><a href="#features" className="button-base border border-white/15 bg-white/10 text-white hover:bg-white/15">See what’s inside</a></div></div><div className="relative min-h-[220px] rounded-[24px] border border-white/10 bg-white/[.06] p-5"><div className="absolute right-5 top-5 rounded-xl bg-[#b9f3dc] px-3 py-2 text-[10px] font-bold text-[#123d32]">+ Rs. 84,200</div><div className="absolute left-5 top-5 text-[10px] font-bold uppercase tracking-[.14em] text-white/45">Creator command center</div><div className="absolute inset-x-5 bottom-5 grid grid-cols-3 gap-3"><div className="rounded-2xl bg-white/[.08] p-3"><div className="text-[10px] text-white/50">Store views</div><div className="mt-2 text-[20px] font-bold">12.4k</div><div className="mt-3 flex h-7 items-end gap-1">{[30,44,25,55,66,82,72].map((height, index) => <span key={index} className="w-1.5 rounded-full bg-[#8f86ff]" style={{ height: `${height}%` }} />)}</div></div><div className="rounded-2xl bg-white/[.08] p-3"><div className="text-[10px] text-white/50">Products</div><div className="mt-2 text-[20px] font-bold">08</div><div className="mt-3 text-[10px] text-[#b9f3dc]">Ready to sell</div></div><div className="rounded-2xl bg-white/[.08] p-3"><div className="text-[10px] text-white/50">Customers</div><div className="mt-2 text-[20px] font-bold">248</div><div className="mt-3 text-[10px] text-white/50">Owned by you</div></div></div></div></div></section>
