function FeatureCard({ icon: Icon, title, copy, className = "" }: { icon: typeof Sparkles; title: string; copy: string; className?: string }) {
  return <div className={`group relative overflow-hidden rounded-[24px] border border-white bg-white p-7 shadow-[0_10px_35px_rgba(28,29,62,.04)] transition duration-200 hover:-translate-y-1 hover:shadow-[0_18px_45px_rgba(28,29,62,.08)] ${className}`}><div className="absolute -right-10 -top-10 size-36 rounded-full bg-lilac/40 blur-3xl transition group-hover:bg-lilac" /><div className="feature-graphic" aria-hidden="true"><span /><span /><span /><span /><span /></div><span className="relative grid size-11 place-items-center rounded-2xl bg-lilac text-indigo"><Icon size={20} /></span><h3 className="relative mt-16 font-display text-[24px] font-semibold tracking-[-.045em]">{title}</h3><p className="relative mt-3 max-w-[330px] text-[13px] leading-6 text-slate-500">{copy}</p></div>;
}

function AuthLayout({ children, label, title, copy }: { children: ReactNode; label: string; title: string; copy: string }) {
  return <div className="grid min-h-screen lg:grid-cols-[1.08fr_.92fr]"><div className="relative hidden overflow-hidden bg-[#191932] p-12 lg:block"><div className="absolute inset-0 opacity-70"><div className="auth-grid" /><div className="absolute -left-20 top-20 size-72 rounded-full bg-indigo/30 blur-[90px]" /><div className="absolute bottom-10 right-0 size-80 rounded-full bg-violet-500/20 blur-[100px]" /></div><div className="relative z-10 flex h-full flex-col"><Logo light /><div className="mt-auto max-w-[520px] pb-10"><div className="eyebrow text-lilac"><span className="size-1.5 rounded-full bg-lilac" /> The calm commerce stack</div><h2 className="mt-5 font-display text-[60px] font-semibold leading-[.98] tracking-[-.07em] text-white">Make space<br />for the work<br /><span className="text-lilac">that matters.</span></h2><p className="mt-6 max-w-[400px] text-[15px] leading-7 text-white/50">A premium home for your products, your customers, and the ideas you’re building next.</p></div><div className="flex items-center gap-3 text-[11px] font-medium text-white/35"><span>moonstore / preview</span><span className="size-1 rounded-full bg-white/20" /><span>Local demo environment</span></div></div></div><div className="flex items-center justify-center bg-[#fbfbfe] px-5 py-10 sm:px-10"><div className="w-full max-w-[430px]"><div className="mb-10 lg:hidden"><Logo /></div><div className="eyebrow">{label}</div><h1 className="mt-4 font-display text-[42px] font-semibold leading-[1.02] tracking-[-.06em]">{title}</h1><p className="mt-4 text-[14px] leading-6 text-slate-500">{copy}</p><div className="mt-9">{children}</div></div></div></div>;
}

function Login() {
  const [, setLocation] = useLocation(); const { setLoggedIn } = useMoonStore(); const [email, setEmail] = useState("ayesha@moonstore.demo"); const [password, setPassword] = useState("demo123"); const [error, setError] = useState("");
  const submit = (event: FormEvent) => { event.preventDefault(); if (!email.includes("@") || password.length < 6) { setError("Enter a valid email and a password with at least 6 characters."); return; } setLoggedIn(true); toast.success("Welcome back to your workspace."); setLocation("/dashboard"); };
  return <AuthLayout label="Welcome back" title="Good to see you again." copy="Your store is ready when you are. This demo login works locally — no account or backend required."><form onSubmit={submit} className="space-y-5"><Field label="Email address" type="email" value={email} onChange={(e) => setEmail(e.target.value)} error={error && !email.includes("@") ? "Enter a valid email address." : undefined} /><Field label="Password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} error={error && password.length < 6 ? "Use at least 6 characters." : undefined} /><div className="flex items-center justify-between text-[12px]"><label className="flex items-center gap-2 text-slate-500"><input type="checkbox" defaultChecked className="size-3.5 accent-indigo" /> Remember me</label><Link href="/forgot-password" className="font-semibold text-indigo hover:text-indigo-dark">Forgot password?</Link></div>{error && <p className="rounded-xl bg-red-50 px-3 py-2.5 text-[12px] font-medium text-red-600">{error}</p>}<PillButton type="submit" icon={ArrowRight}>Log in</PillButton><div className="relative py-1 text-center text-[11px] text-slate-400"><span className="relative z-10 bg-[#fbfbfe] px-3">or continue with</span><span className="absolute left-0 right-0 top-1/2 h-px bg-line" /></div><button type="button" onClick={() => { setLoggedIn(true); toast.success("Google demo access granted."); setLocation("/dashboard"); }} className="button-base button-secondary w-full"><span className="font-bold text-red-500">G</span> Continue with Google</button><p className="pt-3 text-center text-[13px] text-slate-500">Don’t have an account? <Link href="/register" className="font-semibold text-indigo">Create account</Link></p></form></AuthLayout>;
}

function Register() {
  const [, setLocation] = useLocation(); const { updateCreator, finishOnboarding } = useMoonStore(); const [form, setForm] = useState({ name: "", email: "", password: "", username: "" }); const [error, setError] = useState(""); const set = (key: keyof typeof form, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => { event.preventDefault(); if (!form.name || !form.email.includes("@") || form.password.length < 6 || !/^[a-z0-9_]{3,30}$/.test(form.username.toLowerCase())) { setError("Complete all fields. Username: 3–30 lowercase letters, numbers, or underscores."); return; } updateCreator({ name: form.name, email: form.email, username: form.username.toLowerCase() }); finishOnboarding(); toast.success("Your demo workspace is ready."); setLocation("/onboarding"); };
  return <AuthLayout label="Start building" title="Your next chapter starts here." copy="Create a demo workspace in under a minute. You can change every detail later."><form onSubmit={submit} className="space-y-4"><Field label="Your name" value={form.name} onChange={(e) => set("name", e.target.value)} placeholder="Ayesha Malik" /><Field label="Email address" type="email" value={form.email} onChange={(e) => set("email", e.target.value)} placeholder="you@example.com" /><Field label="Choose a username" value={form.username} onChange={(e) => set("username", e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, ""))} placeholder="your_name" hint={form.username ? `Your store: moonstore.com/${form.username}` : "Letters, numbers, and underscores only"} /><Field label="Password" type="password" value={form.password} onChange={(e) => set("password", e.target.value)} placeholder="At least 6 characters" />{error && <p className="rounded-xl bg-red-50 px-3 py-2.5 text-[12px] font-medium text-red-600">{error}</p>}<label className="flex items-start gap-2 pt-1 text-[11px] leading-5 text-slate-500"><input required type="checkbox" className="mt-1 size-3.5 accent-indigo" /> I agree to the demo terms and understand this is a local prototype.</label><PillButton type="submit" icon={ArrowRight}>Create my store</PillButton><p className="pt-2 text-center text-[13px] text-slate-500">Already have a workspace? <Link href="/login" className="font-semibold text-indigo">Log in</Link></p></form></AuthLayout>;
}

function ForgotPassword() {
  const [sent, setSent] = useState(false); const [email, setEmail] = useState("");
  return <AuthLayout label="Account recovery" title="Get back to creating." copy="Enter your email and we’ll show the next step. In this prototype, nothing is sent externally.">{sent ? <div className="rounded-2xl border border-emerald-100 bg-emerald-50 p-5"><span className="grid size-10 place-items-center rounded-xl bg-white text-emerald-600"><Check size={18} /></span><h3 className="mt-4 font-display text-[19px] font-semibold">Demo reset link prepared</h3><p className="mt-2 text-[13px] leading-6 text-emerald-800/70">No email provider is connected yet, but your recovery request was handled safely in the demo.</p><Link href="/login" className="button-base button-primary mt-5">Back to login</Link></div> : <form onSubmit={(e) => { e.preventDefault(); if (!email.includes("@")) return; setSent(true); }} className="space-y-5"><Field label="Email address" value={email} onChange={(e) => setEmail(e.target.value)} type="email" placeholder="you@example.com" /><PillButton type="submit" icon={ArrowRight}>Prepare reset link</PillButton><Link href="/login" className="button-base button-quiet w-full"><ArrowLeft size={15} /> Back to login</Link></form>}</AuthLayout>;
}

function Onboarding() {
  const [, setLocation] = useLocation(); const { data, updateCreator, updateTheme, addProduct, finishOnboarding } = useMoonStore(); const [step, setStep] = useState(1); const [title, setTitle] = useState(""); const [theme, setTheme] = useState<ThemePreset>(data.store.theme.preset); const [error, setError] = useState("");
  const next = () => { if (step === 2 && !/^[a-z0-9_]{3,30}$/.test(data.creator.username)) { setError("Use 3–30 lowercase letters, numbers, or underscores."); return; } if (step === 5 && title.trim()) addProduct({ title, description: "A new resource for your audience.", type: "digital", price: 1500, currency: "PKR", cover: "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=900&q=85", status: "draft", featured: false, includes: ["Downloadable resource"], files: [{ id: `file_${Date.now()}`, name: `${title.toLowerCase().replace(/\s+/g, "-")}.pdf`, type: "PDF document", size: "2.4 MB" }] }); if (step < 6) setStep(step + 1); else { finishOnboarding(); setLocation("/dashboard"); toast.success("Your store is ready to share."); } };
  return <div className="min-h-screen bg-[#fbfbfe] px-5 py-6 sm:px-10"><div className="mx-auto max-w-[960px]"><div className="flex items-center justify-between"><Logo /><span className="text-[12px] font-medium text-slate-400">Step {step} of 6</span></div><div className="mt-8 h-1 overflow-hidden rounded-full bg-line"><div className="h-full rounded-full bg-indigo transition-all" style={{ width: `${(step / 6) * 100}%` }} /></div><div className="mx-auto max-w-[650px] py-16 sm:py-20">{step === 1 && <OnboardCard eyebrow="Welcome to MoonStore" title={`Let’s make a home for ${data.creator.name || "your work"}.`} copy="A few thoughtful choices and you’ll have a beautiful storefront ready to share."><div className="mt-10 grid gap-3 sm:grid-cols-3">{[[Globe2, "One link", "Everything in one place"], [ShoppingBag, "Sell simply", "Products to payments"], [Sparkles, "Built to last", "Your business, your data"]].map(([Icon, title, copy]) => <div key={title as string} className="rounded-2xl border border-line bg-white p-4"><span className="grid size-9 place-items-center rounded-xl bg-lilac text-indigo"><Icon size={17} /></span><div className="mt-5 text-[13px] font-semibold">{title as string}</div><div className="mt-1 text-[11px] leading-5 text-muted">{copy as string}</div></div>)}</div></OnboardCard>}{step === 2 && <OnboardCard eyebrow="Your storefront address" title="Choose a name people will remember." copy="Keep it close to the way you introduce yourself online."><Field label="Username" value={data.creator.username} onChange={(e) => updateCreator({ username: e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, "") })} hint={`moonstore.com/${data.creator.username || "username"}`} error={error} /></OnboardCard>}{step === 3 && <OnboardCard eyebrow="Your creator profile" title="Tell people what you’re about." copy="This appears at the top of your public storefront."><div className="space-y-5"><Field label="Display name" value={data.creator.name} onChange={(e) => updateCreator({ name: e.target.value })} /><label className="block"><span className="mb-2 block text-[12px] font-semibold">Short bio</span><textarea className="field min-h-[110px] resize-none" value={data.creator.bio} onChange={(e) => updateCreator({ bio: e.target.value })} /></label></div></OnboardCard>}{step === 4 && <OnboardCard eyebrow="Choose a store style" title="Pick a point of view." copy="You can fine-tune every color and block later in the Store Builder."><div className="grid grid-cols-2 gap-3 sm:grid-cols-3">{(Object.keys(themePresets) as ThemePreset[]).map((item) => <button type="button" key={item} onClick={() => { setTheme(item); updateTheme(themePresets[item]); }} className={`theme-choice ${theme === item ? "theme-choice-active" : ""}`} style={{ background: themePresets[item].background, color: themePresets[item].text }}><span className="flex items-center justify-between"><span className="size-3 rounded-full" style={{ background: themePresets[item].accent }} />{theme === item && <Check size={14} />}</span><span className="mt-8 block text-left text-[13px] font-bold">{item}</span><span className="mt-1 block text-left text-[10px] opacity-60">{item === "Dark" ? "Deep and focused" : "Quietly confident"}</span></button>)}</div></OnboardCard>}{step === 5 && <OnboardCard eyebrow="Make your first offer" title="What will you share first?" copy="Start with a digital product. You can add courses, services, and bookings later."><Field label="Product title (optional)" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="The creator field guide" hint="We’ll save it as a draft so you can refine it." /><div className="mt-5 rounded-2xl bg-lilac/60 p-4 text-[12px] leading-5 text-indigo-dark"><Sparkles size={15} className="mb-2" />No pressure to get it perfect. You can always create a product from the dashboard.</div></OnboardCard>}{step === 6 && <OnboardCard eyebrow="You’re ready" title="Your corner of the internet is waiting." copy="Everything is connected. Now make it yours, publish a product, and share the link."><div className="mt-9 rounded-2xl border border-line bg-white p-5"><div className="flex items-center gap-3"><img src={data.creator.avatar} alt="" className="size-12 rounded-full object-cover" /><div><div className="font-semibold">{data.creator.name}</div><div className="text-[12px] text-muted">moonstore.com/{data.creator.username}</div></div><Check className="ml-auto text-emerald-600" size={19} /></div></div></OnboardCard>}<div className="mt-9 flex items-center justify-between"><button onClick={() => step > 1 && setStep(step - 1)} className={`button-base button-quiet ${step === 1 ? "invisible" : ""}`}><ArrowLeft size={15} /> Back</button><PillButton onClick={next} icon={step === 6 ? Rocket : ArrowRight}>{step === 6 ? "Open my dashboard" : step === 1 ? "Let’s go" : "Continue"}</PillButton></div></div></div></div>;
}

function OnboardCard({ eyebrow, title, copy, children }: { eyebrow: string; title: string; copy: string; children: ReactNode }) { return <div className="text-center"><div className="eyebrow justify-center">{eyebrow}</div><h1 className="mt-5 font-display text-[40px] font-semibold leading-[1.03] tracking-[-.06em] sm:text-[54px]">{title}</h1><p className="mx-auto mt-4 max-w-[470px] text-[14px] leading-6 text-muted">{copy}</p><div className="mt-10 text-left">{children}</div></div>; }

function Dashboard() {
  const { data } = useMoonStore(); const paidOrders = data.orders.filter((o) => o.status === "paid"); const revenue = paidOrders.reduce((sum, order) => sum + order.amount, 0); const views = data.analytics.filter((event) => event.type === "store_view").length; const recentOrders = data.orders.slice(0, 4); const topProducts = [...data.products].filter((p) => p.status !== "archived").sort((a, b) => b.sales - a.sales).slice(0, 3); const buckets = Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setDate(date.getDate() - (6 - index)); const key = date.toISOString().slice(0, 10); const total = paidOrders.filter((order) => order.createdAt.slice(0, 10) === key).reduce((sum, order) => sum + order.amount, 0); return { label: date.toLocaleDateString("en", { weekday: "short" }).slice(0, 2), total }; }); const max = Math.max(...buckets.map((item) => item.total), 1);
  return <AppShell><PageHeader eyebrow="Overview" title={`Good morning, ${data.creator.name.split(" ")[0]}.`} description="Here’s what’s happening with your store." actions={<><PillButton href={`/${data.creator.username}`} variant="secondary" icon={ExternalLink}>View store</PillButton><PillButton href="/dashboard/products/new" icon={Plus}>Create product</PillButton></>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Revenue" value={formatMoney(revenue)} delta="Live data" icon={CircleDollarSign} accent="green" /><StatCard label="Orders" value={String(paidOrders.length)} delta={paidOrders.length ? "Paid" : undefined} icon={ShoppingBag} /><StatCard label="Customers" value={String(data.customers.length)} icon={Users} accent="violet" /><StatCard label="Store views" value={String(views)} delta={views ? "Tracking" : undefined} icon={Eye} accent="orange" /></div><div className="mt-4 grid gap-4 xl:grid-cols-[1.55fr_1fr]"><section className="surface-panel p-5 sm:p-6"><div className="flex items-start justify-between"><div><h2 className="section-title">Revenue overview</h2><p className="section-copy">Last 7 days · based on completed demo orders</p></div><span className="grid size-9 place-items-center rounded-xl bg-lilac text-indigo"><BarChart3 size={17} /></span></div><div className="mt-8 flex h-[190px] items-end gap-2 border-b border-line sm:gap-4">{buckets.map((item) => <div key={item.label} className="flex min-w-0 flex-1 flex-col items-center gap-2"><div className="relative flex w-full flex-1 items-end justify-center"><div className="chart-bar w-full max-w-[38px] rounded-t-md" style={{ height: `${Math.max(item.total / max * 100, item.total ? 10 : 3)}%` }} title={formatMoney(item.total)} /></div><span className="text-[10px] font-medium text-muted">{item.label}</span></div>)}</div><div className="mt-4 flex items-center justify-between text-[11px] text-muted"><span>Today</span><span className="font-semibold text-ink">{formatMoney(revenue)} total</span></div></section><section className="surface-panel p-5 sm:p-6"><div className="flex items-start justify-between"><div><h2 className="section-title">Store performance</h2><p className="section-copy">A quick read on your funnel</p></div><Link href="/dashboard/analytics" className="text-[11px] font-bold text-indigo">View analytics</Link></div><div className="mt-7 space-y-5">{[["Store views", views, 100, "bg-indigo"], ["Product views", data.analytics.filter((e) => e.type === "product_view").length, Math.max(views, 1), "bg-violet-400"], ["Checkout starts", data.analytics.filter((e) => e.type === "checkout_started").length, Math.max(views, 1), "bg-amber-400"], ["Purchases", paidOrders.length, Math.max(views, 1), "bg-emerald-500"]].map(([label, value, base, color]) => <div key={label as string}><div className="mb-2 flex justify-between text-[12px]"><span className="font-medium text-slate-600">{label as string}</span><span className="font-bold text-ink">{value as number}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-surface"><div className={`h-full rounded-full ${color}`} style={{ width: `${Math.min(100, Math.max((Number(value) / Number(base)) * 100, Number(value) ? 10 : 0))}%` }} /></div></div>)}</div><div className="mt-7 rounded-xl bg-lilac/60 p-3 text-[11px] leading-5 text-indigo-dark"><ShieldCheck size={14} className="mb-1" />Keep sharing your store link to turn attention into useful data.</div></section></div><div className="mt-4 grid gap-4 xl:grid-cols-[1.2fr_.8fr]"><section className="surface-panel"><div className="flex items-center justify-between border-b border-line px-5 py-4"><div><h2 className="section-title">Recent orders</h2><p className="section-copy">Your latest customer activity</p></div><Link href="/dashboard/orders" className="text-[11px] font-bold text-indigo">View all</Link></div>{recentOrders.length ? <div className="divide-y divide-line">{recentOrders.map((order) => <Link key={order.id} href={`/dashboard/orders/${order.id}`} className="flex items-center gap-3 px-5 py-4 transition hover:bg-surface"><span className="grid size-9 place-items-center rounded-xl bg-lilac text-[11px] font-bold text-indigo">{order.customer.name.split(" ").map((n) => n[0]).join("")}</span><div className="min-w-0 flex-1"><div className="truncate text-[13px] font-semibold">{order.customer.name}</div><div className="truncate text-[11px] text-muted">{order.items[0]?.title} · {relativeDate(order.createdAt)}</div></div><div className="text-right"><div className="text-[13px] font-bold">{formatMoney(order.amount)}</div><StatusBadge status={order.status} /></div></Link>)}</div> : <div className="p-5"><EmptyState icon={ShoppingBag} title="Your first sale will appear here." description="Share your store to start collecting orders." /></div>}</section><section className="surface-panel"><div className="flex items-center justify-between border-b border-line px-5 py-4"><div><h2 className="section-title">Top products</h2><p className="section-copy">By completed sales</p></div><Link href="/dashboard/products" className="text-[11px] font-bold text-indigo">Manage</Link></div>{topProducts.length ? <div className="divide-y divide-line">{topProducts.map((product) => <Link key={product.id} href={`/dashboard/products/${product.id}`} className="flex items-center gap-3 px-5 py-4 transition hover:bg-surface"><img src={product.cover} alt="" className="size-10 rounded-xl object-cover" /><div className="min-w-0 flex-1"><div className="truncate text-[13px] font-semibold">{product.title}</div><div className="mt-0.5 text-[11px] text-muted">{product.sales} sales</div></div><div className="text-[12px] font-bold">{formatMoney(product.price)}</div></Link>)}</div> : <div className="p-5"><EmptyState icon={Package} title="No products yet" description="Turn your knowledge or digital files into something people can buy." action={<PillButton href="/dashboard/products/new" icon={Plus}>Create product</PillButton>} /></div>}</section></div></AppShell>;
}

function StoreBuilder() {
  const { data, updateCreator, updateTheme, addBlock, updateBlock, deleteBlock, moveBlock, reorderBlocks } = useMoonStore(); const [selected, setSelected] = useState<string | null>(data.store.blocks[0]?.id ?? null); const [draggingId, setDraggingId] = useState<string | null>(null); const [dragOverId, setDragOverId] = useState<string | null>(null); const selectedBlock = data.store.blocks.find((block) => block.id === selected); const [copied, setCopied] = useState(false); const previewUrl = `moonstore.com/${data.creator.username}`;
  const library: Array<[StoreBlock["type"], string, React.ComponentType<{ size?: number }>] > = [["profile", "Profile", Users], ["text", "Text", FileText], ["image", "Image", ImageIcon], ["product", "Product", Package], ["service", "Service", ClipboardList], ["course", "Course", BookOpen], ["booking", "Booking", CalendarDays], ["button", "Button", Link2], ["whatsapp", "WhatsApp", MessageCircle], ["social", "Social links", Instagram], ["video", "Video", Video], ["divider", "Divider", SlidersHorizontal]];
  return <AppShell><PageHeader eyebrow="Store builder" title="Shape your storefront." description="Choose a block to add, then edit its content in the settings panel. Your public page updates instantly." actions={<><button className="button-base button-secondary" onClick={() => { navigator.clipboard?.writeText(`https://${previewUrl}`); setCopied(true); setTimeout(() => setCopied(false), 1600); }}>{copied ? <Check size={15} /> : <Copy size={15} />}{copied ? "Copied" : "Copy link"}</button><PillButton href={`/${data.creator.username}`} icon={ExternalLink}>Preview store</PillButton></>} /><div className="builder-grid"><section className="surface-panel min-h-[660px] p-4"><div className="mb-4 flex items-center justify-between"><div><div className="text-[12px] font-bold">Add a block</div><div className="mt-1 text-[11px] text-muted">Choose what belongs on your page</div></div><Plus size={16} className="text-muted" /></div><div className="grid grid-cols-2 gap-2">{library.map(([type, label, Icon]) => <button key={type} onClick={() => { const existingBlock = data.store.blocks.find((block) => block.type === type && ["profile", "social"].includes(type)); if (existingBlock) { setSelected(existingBlock.id); toast(`${label} is already on your page. Selected it for editing.`); return; } if (type === "product" && !data.products.some((product) => product.status === "published")) { toast.error("Publish a product before adding a Product block."); return; } const id = addBlock(type); setSelected(id); toast.success(`${label} block added. Configure it on the right.`); }} className="builder-library-item"><Icon size={16} /><span>{label}</span></button>)}</div><details open className="mt-7 border-t border-line pt-5"><summary className="flex cursor-pointer list-none items-center justify-between"><span className="text-[10px] font-bold uppercase tracking-[.14em] text-muted">Your page</span><span className="flex items-center gap-2 text-[10px] font-semibold text-muted">{data.store.blocks.length} blocks <ChevronDown size={13} /></span></summary><div className="mt-3 space-y-1">{data.store.blocks.map((block, index) => <button key={block.id} draggable onDragStart={(event) => { setDraggingId(block.id); event.dataTransfer.setData("text/plain", block.id); event.dataTransfer.effectAllowed = "move"; }} onDragEnd={() => { setDraggingId(null); setDragOverId(null); }} onDragEnter={() => setDragOverId(block.id)} onDragOver={(event) => { event.preventDefault(); setDragOverId(block.id); }} onDrop={(event) => { event.preventDefault(); const source = event.dataTransfer.getData("text/plain"); if (source && source !== block.id) { reorderBlocks(source, block.id); toast.success("Block order updated."); } setDraggingId(null); setDragOverId(null); }} onClick={() => setSelected(block.id)} className={`builder-page-item relative flex w-full items-center gap-2 rounded-lg px-2 py-2 text-left text-[11px] transition hover:bg-surface ${selected === block.id ? "bg-lilac font-semibold text-indigo" : "text-slate-600"} ${dragOverId === block.id && draggingId !== block.id ? "builder-drop-active" : ""} ${draggingId === block.id ? "opacity-50" : ""}`}><GripVertical size={12} className="shrink-0 text-muted" /><span className="grid size-5 place-items-center rounded-md bg-surface text-[9px] font-bold">{index + 1}</span><span className="capitalize">{block.type}</span><span className="ml-auto text-[9px] text-muted">{block.visible ? "Visible" : "Hidden"}</span></button>)}</div></details><details className="mt-5 border-t border-line pt-5"><summary className="flex cursor-pointer list-none items-center justify-between"><span className="text-[10px] font-bold uppercase tracking-[.14em] text-muted">Store style</span><ChevronDown size={13} className="text-muted" /></summary><div className="mt-3 space-y-1">{(Object.keys(themePresets) as ThemePreset[]).map((preset) => <button key={preset} onClick={() => { updateTheme(themePresets[preset]); toast.success(`${preset} theme applied.`); }} className={`flex w-full items-center gap-2 rounded-lg px-2 py-2 text-left text-[12px] transition hover:bg-surface ${data.store.theme.preset === preset ? "bg-lilac font-semibold text-indigo" : "text-slate-600"}`}><span className="size-3 rounded-full border border-black/10" style={{ background: themePresets[preset].accent }} />{preset}{data.store.theme.preset === preset && <Check size={13} className="ml-auto" />}</button>)}</div></details></section><section className="builder-preview rounded-2xl border border-line bg-[#edf0f8] p-4 sm:p-7"><div className="mb-4 flex items-center justify-between text-[11px] font-semibold text-muted"><span className="flex items-center gap-2"><span className="size-2 rounded-full bg-emerald-500" /> Live preview</span><span>Mobile storefront</span></div><div className="mx-auto min-h-[600px] max-w-[390px] overflow-hidden rounded-[28px] border-[7px] border-ink bg-white shadow-2xl"><StorefrontContent compact interactive onSelectBlock={setSelected} /></div></section><section className="surface-panel min-h-[660px] p-5"><div className="mb-5 flex items-center justify-between"><div><div className="text-[12px] font-bold">Block settings</div><div className="mt-1 text-[11px] text-muted">{selectedBlock ? "Edit selected block" : "Select a block from Your page"}</div></div><Settings2 size={16} className="text-muted" /></div>{selectedBlock ? <BlockSettings block={selectedBlock} onUpdate={updateBlock} onDelete={() => { deleteBlock(selectedBlock.id); setSelected(null); toast.success("Block removed."); }} onUpdateCreator={updateCreator} /> : <EmptyState icon={Settings2} title="Choose a block" description="Use Your page on the left to select a section, then edit its content here." />}</section></div></AppShell>;
}

function BlockSettings({ block, onUpdate, onDelete, onUpdateCreator }: { block: StoreBlock; onUpdate: (id: string, patch: Partial<StoreBlock>) => void; onDelete: () => void; onUpdateCreator: (patch: Partial<ReturnType<typeof useMoonStore>["data"]["creator"]>) => void }) {
  const { data, moveBlock } = useMoonStore();
  return <div className="space-y-5">
    <div className="flex items-center justify-between rounded-xl bg-surface p-3"><div className="flex items-center gap-2"><GripVertical size={14} className="text-muted" /><span className="text-[12px] font-semibold capitalize">{block.type} block</span></div><button onClick={() => onUpdate(block.id, { visible: !block.visible })} className={`toggle ${block.visible ? "toggle-on" : ""}`}><span /></button></div>
    {block.type === "profile" && <div className="space-y-5"><div className="rounded-xl bg-surface p-3 text-[11px] leading-5 text-muted">Connected to your creator profile. Changes here update the public storefront immediately.</div><Field label="Display name" value={data.creator.name} onChange={(e) => onUpdateCreator({ name: e.target.value })} /><label className="block"><span className="mb-2 block text-[12px] font-semibold">Bio</span><textarea className="field min-h-[100px] resize-none" value={data.creator.bio} onChange={(e) => onUpdateCreator({ bio: e.target.value })} /></label><Field label="Avatar image URL" value={data.creator.avatar} onChange={(e) => onUpdateCreator({ avatar: e.target.value })} hint="Use an image URL for this local prototype." /></div>}
    {block.type === "social" && <div className="space-y-4">{data.creator.socials.map((social, index) => <div key={social.label} className="rounded-xl bg-surface p-3"><div className="mb-3 text-[11px] font-bold">{social.label}</div><Field label="Link URL" value={social.url} onChange={(e) => onUpdateCreator({ socials: data.creator.socials.map((item, itemIndex) => itemIndex === index ? { ...item, url: e.target.value } : item) })} /></div>)}</div>}
    {block.type === "text" && <><Field label="Heading" value={block.title ?? ""} onChange={(e) => onUpdate(block.id, { title: e.target.value })} /><label className="block"><span className="mb-2 block text-[12px] font-semibold">Body copy</span><textarea className="field min-h-[100px] resize-none" value={block.body ?? ""} onChange={(e) => onUpdate(block.id, { body: e.target.value })} /></label></>}
    {block.type === "button" && <Field label="Button label" value={block.buttonLabel ?? ""} onChange={(e) => onUpdate(block.id, { buttonLabel: e.target.value })} />}
    {block.type === "product" && <SelectField label="Featured product" value={block.productId ?? ""} onChange={(value) => onUpdate(block.id, { productId: value })}><option value="">Choose a product</option>{data.products.filter((p) => p.status === "published").map((product) => <option key={product.id} value={product.id}>{product.title}</option>)}</SelectField>}
    {block.type === "image" && <Field label="Image URL" value={block.imageUrl ?? ""} onChange={(e) => onUpdate(block.id, { imageUrl: e.target.value })} placeholder="https://images.unsplash.com/..." hint="Use an image URL for this local prototype." />}
    {["service", "course", "booking"].includes(block.type) && <><Field label="Offer title" value={block.title ?? ""} onChange={(e) => onUpdate(block.id, { title: e.target.value })} /><label className="block"><span className="mb-2 block text-[12px] font-semibold">Offer description</span><textarea className="field min-h-[92px] resize-none" value={block.body ?? ""} onChange={(e) => onUpdate(block.id, { body: e.target.value })} /></label><div className="grid gap-3 sm:grid-cols-2"><Field label="Rate" type="number" min="0" value={String(block.price ?? 0)} onChange={(e) => onUpdate(block.id, { price: Number(e.target.value) })} placeholder="2500" /><Field label="Currency" value={block.currency ?? "PKR"} onChange={(e) => onUpdate(block.id, { currency: e.target.value.toUpperCase() })} /></div><Field label="Availability" value={block.availability ?? "Open for bookings"} onChange={(e) => onUpdate(block.id, { availability: e.target.value })} hint="Example: 4 spots left, self-paced, or weekdays." /><Field label="Button label" value={block.buttonLabel ?? "Get started"} onChange={(e) => onUpdate(block.id, { buttonLabel: e.target.value })} />{block.type === "booking" && <Field label="Scheduling link" value={block.schedulingUrl ?? ""} onChange={(e) => onUpdate(block.id, { schedulingUrl: e.target.value })} placeholder="https://cal.com/your-name" hint="Paste a Cal.com, Calendly, or other public booking URL." />}</>}{["whatsapp", "video", "divider"].includes(block.type) && <div className="rounded-xl border border-line bg-surface p-3 text-[12px] leading-5 text-muted">This {block.type} block is ready in the storefront layout and can be moved, hidden, or deleted here.</div>}
    <div className="flex gap-2 border-t border-line pt-5"><button onClick={() => moveBlock(block.id, -1)} className="button-base button-secondary flex-1">Move up</button><button onClick={() => moveBlock(block.id, 1)} className="button-base button-secondary flex-1">Move down</button></div><button onClick={onDelete} className="button-base button-danger w-full"><Trash2 size={15} /> Delete block</button>
  </div>;
}

function StorefrontContent({ compact = false, interactive = false, onSelectBlock }: { compact?: boolean; interactive?: boolean; onSelectBlock?: (id: string) => void }) {
  const { data } = useMoonStore(); const { creator, store, products } = data; const handlePreviewClick = (event: React.MouseEvent<HTMLDivElement>) => { if (!interactive) return; const target = (event.target as HTMLElement).closest("[data-block-id]") as HTMLElement | null; if (target?.dataset.blockId) { event.preventDefault(); event.stopPropagation(); onSelectBlock?.(target.dataset.blockId); } }; const visibleBlocks = store.blocks.filter((block) => block.visible); const theme = store.theme; const cardClass = theme.card === "outline" ? "border border-current/15 bg-transparent" : theme.card === "solid" ? "bg-white/70" : "bg-black/[.04]";
  return <div onClickCapture={handlePreviewClick} className={`min-h-full p-5 sm:p-7 ${compact ? "text-[.9em]" : ""}`} style={{ background: theme.background, color: theme.text, fontFamily: theme.font }}><div className="mx-auto max-w-[570px]">{visibleBlocks.map((block) => { const product = block.productId ? products.find((item) => item.id === block.productId && item.status === "published") : undefined; if (block.type === "profile") return <div key={block.id} data-block-id={block.id} className="text-center"><img src={creator.avatar} alt={creator.name} className="mx-auto size-20 rounded-full object-cover ring-4 ring-current/5" /><div className="mt-4 text-[18px] font-bold tracking-[-.03em]">{creator.name}</div><div className="mt-1 text-[11px] opacity-55">@{creator.username}</div><p className="mx-auto mt-4 max-w-[370px] text-[13px] leading-6 opacity-75">{creator.bio}</p><div className="mt-4 flex justify-center gap-2">{creator.socials.map((social) => <span key={social.label} className="grid size-8 place-items-center rounded-full border border-current/10 opacity-70"><SocialIcon name={social.icon} /></span>)}</div></div>; if (block.type === "text") return <div key={block.id} data-block-id={block.id} className="mt-7 text-center"><h2 className="font-display text-[25px] font-semibold leading-[1.04] tracking-[-.05em]">{block.title}</h2><p className="mt-3 text-[12px] leading-5 opacity-65">{block.body}</p></div>; if (block.type === "product" && product) return <Link key={block.id} data-block-id={block.id} href={`/${creator.username}/${product.slug}`} className={`group mt-6 block overflow-hidden rounded-2xl ${cardClass}`}><img src={product.cover} alt="" className="h-36 w-full object-cover transition duration-300 group-hover:scale-[1.02]" /><div className="flex items-center justify-between gap-4 p-4"><div><div className="text-[13px] font-bold">{product.title}</div><div className="mt-1 text-[10px] uppercase tracking-[.12em] opacity-55">{PRODUCT_TYPE_LABELS[product.type]}</div></div><span className="shrink-0 text-[13px] font-bold" style={{ color: theme.accent }}>{formatMoney(product.price, product.currency)}</span></div></Link>; if (block.type === "image") return block.imageUrl ? <img key={block.id} data-block-id={block.id} src={block.imageUrl} alt="Store visual" className="mt-6 h-40 w-full rounded-2xl object-cover" /> : <div key={block.id} className="mt-6 flex h-40 items-center justify-center rounded-2xl border border-dashed border-current/20 text-center text-[11px] opacity-55">Add an image URL in block settings</div>; if (block.type === "button") return <button key={block.id} data-block-id={block.id} onClick={() => toast("This button is ready for your custom destination.")} className="mt-6 w-full rounded-xl px-4 py-3 text-[12px] font-bold text-white transition hover:opacity-90" style={{ background: theme.accent, borderRadius: theme.button === "pill" ? 999 : theme.button === "square" ? 5 : 12 }}>{block.buttonLabel || "Explore"}</button>; if (block.type === "social") return <div key={block.id} data-block-id={block.id} className="mt-7 flex justify-center gap-2">{creator.socials.map((social) => <a href={social.url} target="_blank" rel="noreferrer" key={social.label} className={`rounded-full px-3 py-2 text-[10px] font-semibold ${cardClass}`}>{social.label}</a>)}</div>; if (block.type === "whatsapp") return <button key={block.id} data-block-id={block.id} className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-[#25D366] px-4 py-3 text-[12px] font-bold text-white" onClick={() => toast("WhatsApp is a demo destination in this prototype.")}><MessageCircle size={15} /> Message on WhatsApp</button>; if (block.type === "divider") return <div key={block.id} data-block-id={block.id} className="my-7 h-px bg-current/10" />; if (["service", "course", "booking"].includes(block.type)) return <div key={block.id} data-block-id={block.id} className={`mt-6 rounded-2xl p-4 ${cardClass}`}><div className="flex items-start gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-xl text-white" style={{ background: theme.accent }}><CalendarDays size={16} /></span><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><div className="text-[13px] font-bold">{block.title || (block.type === "course" ? "Learn with me" : block.type === "booking" ? "Book a session" : "Work with me")}</div>{Number(block.price) > 0 && <span className="text-[12px] font-bold" style={{ color: theme.accent }}>{formatMoney(Number(block.price), block.currency || "PKR")}</span>}</div><div className="mt-1 text-[11px] leading-5 opacity-60">{block.body || "A focused way to work together."}</div><div className="mt-2 text-[10px] font-semibold opacity-55">{block.availability || "Open for bookings"}</div>{block.type === "booking" && block.schedulingUrl ? <a className="mt-3 inline-flex rounded-lg px-3 py-2 text-[10px] font-bold text-white" style={{ background: theme.accent }} href={block.schedulingUrl} target="_blank" rel="noreferrer">{block.buttonLabel || "Choose a time"}</a> : <button className="mt-3 rounded-lg px-3 py-2 text-[10px] font-bold text-white" style={{ background: theme.accent }} onClick={() => toast(`${block.title || "This offer"} is ready for your audience.`)}>{block.buttonLabel || (block.type === "booking" ? "Choose a time" : "Get started")}</button>}</div></div></div>; if (block.type === "video") return <div key={block.id} data-block-id={block.id} className={`mt-6 flex h-36 items-center justify-center rounded-2xl ${cardClass}`}><span className="grid size-12 place-items-center rounded-full bg-current/10"><Play size={18} /></span></div>; return null; })}<div className="mt-9 text-center text-[10px] font-semibold opacity-30">made with moonstore</div></div></div>;
}

function SocialIcon({ name }: { name: string }) { if (name === "instagram") return <Instagram size={14} />; if (name === "youtube") return <Youtube size={14} />; return <span className="text-[11px] font-bold">♪</span>; }

function Products() {
  const { data, updateProduct, deleteProduct } = useMoonStore(); const [query, setQuery] = useState(""); const [status, setStatus] = useState("all"); const [type, setType] = useState("all"); const [view, setView] = useState<"grid" | "list">("grid"); const [menu, setMenu] = useState<string | null>(null); const filtered = data.products.filter((product) => (!query || `${product.title} ${product.description}`.toLowerCase().includes(query.toLowerCase())) && (status === "all" || product.status === status) && (type === "all" || product.type === type));
  return <AppShell><PageHeader eyebrow="Catalog" title="Products" description={`${data.products.length} products in your workspace.`} actions={<PillButton href="/dashboard/products/new" icon={Plus}>Create product</PillButton>} /><div className="mb-5 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div className="relative w-full max-w-[360px]"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search products" className="field pl-9" /></div><div className="flex flex-wrap items-center gap-2"><div className="filter-pills">{["all", "published", "draft", "archived"].map((item) => <button key={item} onClick={() => setStatus(item)} className={status === item ? "active" : ""}>{item}</button>)}</div><select value={type} onChange={(e) => setType(e.target.value)} className="field h-9 w-auto py-1.5 text-[12px]"><option value="all">All types</option>{Object.entries(PRODUCT_TYPE_LABELS).map(([key, value]) => <option key={key} value={key}>{value}</option>)}</select><div className="hidden items-center rounded-lg border border-line bg-white p-0.5 sm:flex"><button onClick={() => setView("grid")} className={`icon-button size-8 ${view === "grid" ? "bg-lilac text-indigo" : ""}`}><LayoutGrid size={15} /></button><button onClick={() => setView("list")} className={`icon-button size-8 ${view === "list" ? "bg-lilac text-indigo" : ""}`}><List size={15} /></button></div></div></div>{filtered.length ? view === "grid" ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{filtered.map((product) => <ProductCard key={product.id} product={product} menu={menu === product.id} onMenu={() => setMenu(menu === product.id ? null : product.id)} onArchive={() => { updateProduct(product.id, { status: product.status === "archived" ? "draft" : "archived" }); setMenu(null); toast.success(product.status === "archived" ? "Product restored to drafts." : "Product archived."); }} onDelete={() => { deleteProduct(product.id); setMenu(null); toast.success("Product deleted."); }} />)}</div> : <div className="surface-panel divide-y divide-line">{filtered.map((product) => <ProductRow key={product.id} product={product} onArchive={() => updateProduct(product.id, { status: product.status === "archived" ? "draft" : "archived" })} />)}</div> : <EmptyState icon={Package} title={query || status !== "all" ? "No matching products" : "No products yet"} description={query || status !== "all" ? "Try another search or filter." : "Turn your knowledge or digital files into something people can buy."} action={<PillButton href="/dashboard/products/new" icon={Plus}>Create product</PillButton>} />}</AppShell>;
}

function ProductCard({ product, menu, onMenu, onArchive, onDelete }: { product: Product; menu: boolean; onMenu: () => void; onArchive: () => void; onDelete: () => void }) { return <div className="surface-panel group overflow-visible"><div className="relative overflow-hidden rounded-t-2xl"><img src={product.cover} alt="" className="h-[185px] w-full object-cover transition duration-300 group-hover:scale-[1.02]" /><div className="absolute left-3 top-3"><StatusBadge status={product.status} /></div><div className="absolute right-3 top-3"><button onClick={onMenu} className="grid size-8 place-items-center rounded-lg bg-white/90 text-ink shadow-sm backdrop-blur"><MoreHorizontal size={16} /></button>{menu && <div className="absolute right-0 top-10 z-20 w-36 rounded-xl border border-line bg-white p-1.5 shadow-xl"><Link href={`/dashboard/products/${product.id}`} className="menu-item"><Edit3 size={13} />Edit</Link><button onClick={onArchive} className="menu-item">{product.status === "archived" ? <RefreshCw size={13} /> : <ArchiveIcon size={13} />}{product.status === "archived" ? "Restore" : "Archive"}</button><button onClick={onDelete} className="menu-item text-red-600"><Trash2 size={13} />Delete</button></div>}</div></div><div className="p-4"><div className="flex items-start justify-between gap-3"><div><div className="line-clamp-1 text-[14px] font-bold tracking-[-.02em]">{product.title}</div><div className="mt-1 text-[11px] text-muted">{PRODUCT_TYPE_LABELS[product.type]}</div></div><div className="text-[13px] font-bold">{formatMoney(product.price)}</div></div><div className="mt-5 flex items-center justify-between text-[11px] text-muted"><span>{product.sales} sales</span><span>Updated {relativeDate(product.updatedAt)}</span></div></div></div>; }
function ProductRow({ product, onArchive }: { product: Product; onArchive: () => void }) { return <div className="flex flex-col gap-3 px-5 py-4 sm:flex-row sm:items-center"><img src={product.cover} alt="" className="size-11 rounded-xl object-cover" /><div className="min-w-0 flex-1"><Link href={`/dashboard/products/${product.id}`} className="line-clamp-1 text-[13px] font-bold hover:text-indigo">{product.title}</Link><div className="mt-1 text-[11px] text-muted">{PRODUCT_TYPE_LABELS[product.type]} · {product.sales} sales</div></div><div className="flex items-center gap-5"><span className="text-[13px] font-bold">{formatMoney(product.price)}</span><StatusBadge status={product.status} /><button onClick={onArchive} className="icon-button" aria-label="Archive product"><ArchiveIcon size={15} /></button></div></div>; }
function ArchiveIcon({ size = 15 }: { size?: number }) { return <span className="text-[13px]">▱</span>; }

function ProductEditor() {
  const { data, addProduct, updateProduct } = useMoonStore(); const [, params] = useRoute("/dashboard/products/:id"); const editing = Boolean(params?.id && params.id !== "new"); const existing = data.products.find((p) => p.id === params?.id); const [, setLocation] = useLocation(); const [step, setStep] = useState(1); const [saved, setSaved] = useState(false); const [form, setForm] = useState(() => existing ? { title: existing.title, description: existing.description, price: String(existing.price), type: existing.type, cover: existing.cover, status: existing.status, includes: existing.includes.join("\n") } : { title: "", description: "", price: "", type: "digital" as ProductType, cover: "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=900&q=85", status: "draft" as const, includes: "" }); const [error, setError] = useState(""); if (editing && !existing) return <NotFound title="Product not found" copy="This product may have been removed from your catalog." />; const update = (key: string, value: string) => setForm((current) => ({ ...current, [key]: value })); const save = (publish = false) => { if (!form.title.trim()) { setError("Add a title for your product."); setStep(2); return; } if (!form.price || Number(form.price) < 0) { setError("Enter a valid price."); setStep(4); return; } const input = { title: form.title.trim(), description: form.description.trim(), type: form.type as ProductType, price: Number(form.price), currency: "PKR", cover: form.cover, status: publish ? "published" as const : form.status as "published" | "draft" | "archived", featured: false, includes: form.includes.split("\n").map((item) => item.trim()).filter(Boolean), files: existing?.files ?? [{ id: `file_${Date.now()}`, name: `${form.title.toLowerCase().replace(/\s+/g, "-")}.pdf`, type: "PDF document", size: "2.4 MB" }] }; if (existing) updateProduct(existing.id, input); else addProduct(input); setSaved(true); toast.success(existing ? "Product updated." : "Product created."); setTimeout(() => setLocation("/dashboard/products"), 450); };
  return <AppShell><div className="mb-7 flex items-center gap-3"><Link href="/dashboard/products" className="icon-button"><ArrowLeft size={17} /></Link><div className="text-[12px] font-medium text-muted">Products <ChevronRight size={12} className="mx-1 inline" /> {editing ? "Edit product" : "New product"}</div></div><PageHeader eyebrow={editing ? "Edit product" : "Create a product"} title={editing ? form.title : "Turn your idea into an offer."} description="A focused setup for a digital product. Real file storage can be connected later." actions={<><PillButton href={`/${data.creator.username}/${existing?.slug ?? ""}`} variant="secondary" icon={Eye}>Preview</PillButton><PillButton onClick={() => save(true)} icon={Rocket}>{saved ? "Saved" : "Publish"}</PillButton></>} /><div className="mx-auto max-w-[980px]"><div className="mb-6 grid grid-cols-5 gap-1 sm:gap-3">{["Product type", "Details", "Content", "Pricing", "Review"].map((item, index) => <button key={item} onClick={() => setStep(index + 1)} className={`wizard-step ${step === index + 1 ? "wizard-step-active" : step > index + 1 ? "wizard-step-done" : ""}`}><span>{index + 1}</span><span className="hidden sm:inline">{item}</span></button>)}</div><div className="surface-panel p-5 sm:p-8">{step === 1 && <div><h2 className="font-display text-[24px] font-semibold tracking-[-.04em]">What are you selling?</h2><p className="mt-2 text-[13px] text-muted">Start with the product format that best matches your offer.</p><div className="mt-7 grid gap-3 sm:grid-cols-2">{Object.entries(PRODUCT_TYPE_LABELS).map(([key, label]) => <button key={key} onClick={() => { update("type", key); setStep(2); }} className={`product-type-choice ${form.type === key ? "product-type-choice-active" : ""}`}><span className="grid size-10 place-items-center rounded-xl text-white" style={{ background: PRODUCT_TYPE_COLORS[key as ProductType] }}><ProductTypeIcon type={key as ProductType} /></span><span className="text-left"><span className="block text-[13px] font-bold">{label}</span><span className="mt-1 block text-[11px] leading-5 text-muted">{key === "digital" ? "Files, templates, guides" : key === "course" ? "Lessons and learning" : key === "service" ? "An offer delivered by you" : "A time-based experience"}</span></span></button>)}</div></div>}{step === 2 && <div className="max-w-[700px]"><h2 className="font-display text-[24px] font-semibold tracking-[-.04em]">Give it a clear shape.</h2><p className="mt-2 text-[13px] text-muted">A good title and honest description do a lot of the selling.</p><div className="mt-7 space-y-5"><Field label="Product title" value={form.title} onChange={(e) => update("title", e.target.value)} placeholder="The ultimate creator toolkit" error={error && !form.title ? error : undefined} /><label className="block"><span className="mb-2 block text-[12px] font-semibold">Description</span><textarea className="field min-h-[150px] resize-y" value={form.description} onChange={(e) => update("description", e.target.value)} placeholder="What will someone be able to do after buying this?" /></label></div></div>}{step === 3 && <div className="max-w-[700px]"><h2 className="font-display text-[24px] font-semibold tracking-[-.04em]">Add what’s included.</h2><p className="mt-2 text-[13px] text-muted">One item per line. This becomes the buyer’s quick overview.</p><div className="mt-7 space-y-5"><label className="block"><span className="mb-2 block text-[12px] font-semibold">What’s included</span><textarea className="field min-h-[155px] resize-y" value={form.includes} onChange={(e) => update("includes", e.target.value)} placeholder={"40 editable templates\nLaunch checklist\nLifetime updates"} /></label><label className="block"><span className="mb-2 block text-[12px] font-semibold">Cover image URL</span><div className="flex gap-2"><input className="field" value={form.cover} onChange={(e) => update("cover", e.target.value)} /><button type="button" onClick={() => toast("Demo upload only — connect Supabase Storage later.")} className="button-base button-secondary shrink-0"><Upload size={15} /> Upload</button></div><span className="mt-1.5 block text-[11px] text-muted">Demo image handling only. No cloud upload is claimed.</span></label></div></div>}{step === 4 && <div className="max-w-[600px]"><h2 className="font-display text-[24px] font-semibold tracking-[-.04em]">Set your price.</h2><p className="mt-2 text-[13px] text-muted">You can edit this any time. Currency is set to PKR for this demo.</p><div className="mt-7 grid gap-5 sm:grid-cols-2"><Field label="Price" type="number" min="0" value={form.price} onChange={(e) => update("price", e.target.value)} placeholder="2500" error={error && (!form.price || Number(form.price) < 0) ? error : undefined} /><SelectField label="Currency" value="PKR" onChange={() => {}}><option value="PKR">PKR · Pakistani Rupee</option></SelectField></div><div className="mt-6 rounded-xl bg-amber-50 p-4 text-[12px] leading-5 text-amber-800"><WalletCards size={15} className="mb-1" /> Demo checkout will use this price from the local data layer. A real payment provider is not connected.</div></div>}{step === 5 && <div><h2 className="font-display text-[24px] font-semibold tracking-[-.04em]">Review before you share.</h2><p className="mt-2 text-[13px] text-muted">Make sure the essentials are clear. You can publish now or save as a draft.</p><div className="mt-7 grid gap-5 md:grid-cols-[180px_1fr]"><img src={form.cover} alt="" className="h-[140px] w-full rounded-2xl object-cover" /><div><div className="text-[20px] font-bold tracking-[-.03em]">{form.title || "Untitled product"}</div><div className="mt-2 text-[13px] leading-6 text-muted">{form.description || "No description yet."}</div><div className="mt-4 text-[18px] font-bold">{form.price ? formatMoney(Number(form.price)) : "Set a price"}</div></div></div></div>}<div className="mt-9 flex items-center justify-between border-t border-line pt-5"><button onClick={() => step > 1 && setStep(step - 1)} className={`button-base button-quiet ${step === 1 ? "invisible" : ""}`}><ArrowLeft size={15} /> Back</button><div className="flex gap-2">{step < 5 ? <PillButton onClick={() => { setError(""); if (step === 2 && !form.title.trim()) { setError("Add a title for your product."); return; } if (step === 4 && (!form.price || Number(form.price) < 0)) { setError("Enter a valid price."); return; } setStep(step + 1); }} icon={ArrowRight}>Continue</PillButton> : <><button onClick={() => save(false)} className="button-base button-secondary">Save draft</button><PillButton onClick={() => save(true)} icon={Rocket}>Publish product</PillButton></>}</div></div></div></div></AppShell>;
}

function ProductTypeIcon({ type }: { type: ProductType }) { if (type === "digital") return <FileText size={18} />; if (type === "course") return <BookOpen size={18} />; if (type === "service") return <Users size={18} />; return <CalendarDays size={18} />; }

function Orders() {
  const { data } = useMoonStore(); const [query, setQuery] = useState(""); const [status, setStatus] = useState("all"); const [sort, setSort] = useState("newest"); const filtered = [...data.orders].filter((order) => (!query || `${order.number} ${order.customer.name} ${order.customer.email} ${order.items[0]?.title}`.toLowerCase().includes(query.toLowerCase())) && (status === "all" || order.status === status)).sort((a, b) => sort === "newest" ? +new Date(b.createdAt) - +new Date(a.createdAt) : b.amount - a.amount);
  return <AppShell><PageHeader eyebrow="Commerce" title="Orders" description="Every order created by the connected demo checkout." actions={<button onClick={() => toast("Orders export is a coming soon feature.")} className="button-base button-secondary"><Download size={15} /> Export</button>} /><div className="mb-5 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div className="relative w-full max-w-[360px]"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search orders" className="field pl-9" /></div><div className="flex flex-wrap gap-2"><select value={status} onChange={(e) => setStatus(e.target.value)} className="field h-9 w-auto py-1.5 text-[12px]"><option value="all">All statuses</option>{["paid", "pending", "failed", "refunded"].map((item) => <option key={item} value={item}>{item[0].toUpperCase() + item.slice(1)}</option>)}</select><select value={sort} onChange={(e) => setSort(e.target.value)} className="field h-9 w-auto py-1.5 text-[12px]"><option value="newest">Newest first</option><option value="amount">Highest value</option></select></div></div>{filtered.length ? <div className="surface-panel overflow-hidden"><div className="hidden grid-cols-[1.25fr_1.1fr_1.3fr_.7fr_.7fr_.8fr] gap-4 border-b border-line bg-surface px-5 py-3 text-[10px] font-bold uppercase tracking-[.1em] text-muted md:grid"><span>Order</span><span>Customer</span><span>Product</span><span>Amount</span><span>Status</span><span>Date</span></div><div className="divide-y divide-line">{filtered.map((order) => <Link key={order.id} href={`/dashboard/orders/${order.id}`} className="grid gap-2 px-5 py-4 transition hover:bg-surface md:grid-cols-[1.25fr_1.1fr_1.3fr_.7fr_.7fr_.8fr] md:items-center md:gap-4"><div><div className="text-[12px] font-bold text-indigo">{order.number}</div><div className="mt-1 text-[11px] text-muted">{order.isDemo ? "Demo order" : "Order"}</div></div><div><div className="text-[13px] font-semibold">{order.customer.name}</div><div className="text-[11px] text-muted">{order.customer.email}</div></div><div className="truncate text-[12px] text-slate-600">{order.items[0]?.title}</div><div className="text-[13px] font-bold">{formatMoney(order.amount)}</div><StatusBadge status={order.status} /><div className="text-[11px] text-muted">{formatDate(order.createdAt)}</div></Link>)}</div></div> : <EmptyState icon={ShoppingBag} title="Your first sale will appear here." description="When someone completes the demo checkout, the order will be connected to revenue, customers, and analytics." />}</AppShell>;
}

function OrderDetail() { const [, params] = useRoute("/dashboard/orders/:id"); const { data } = useMoonStore(); const order = data.orders.find((item) => item.id === params?.id); if (!order) return <NotFound title="Order not found" copy="This order is not part of the current local workspace." />; return <AppShell><div className="mb-7 flex items-center gap-3"><Link href="/dashboard/orders" className="icon-button"><ArrowLeft size={17} /></Link><div className="text-[12px] font-medium text-muted">Orders <ChevronRight size={12} className="mx-1 inline" /> {order.number}</div></div><PageHeader eyebrow="Order detail" title={order.number} description={`Created ${formatDate(order.createdAt)} · ${order.isDemo ? "Demo checkout" : "Order"}`} actions={<StatusBadge status={order.status} />} /><div className="grid gap-4 lg:grid-cols-[1.15fr_.85fr]"><section className="surface-panel p-5 sm:p-7"><h2 className="section-title">Order summary</h2><div className="mt-6 flex items-center gap-4 rounded-2xl bg-surface p-4"><img src={data.products.find((p) => p.id === order.items[0]?.productId)?.cover ?? ""} alt="" className="size-16 rounded-xl object-cover" /><div className="min-w-0 flex-1"><div className="truncate text-[14px] font-bold">{order.items[0]?.title}</div><div className="mt-1 text-[12px] text-muted">Qty {order.items[0]?.quantity}</div></div><div className="text-[15px] font-bold">{formatMoney(order.amount)}</div></div><div className="mt-7 grid gap-4 border-t border-line pt-6 sm:grid-cols-2"><Info label="Payment method" value={order.paymentMethod} /><Info label="Payment status" value="Demo confirmed" /><Info label="Order status" value={order.status} /><Info label="Total" value={formatMoney(order.amount)} /></div><div className="mt-7 flex flex-wrap gap-2"><PillButton href={`/download/${order.id}`} icon={Download}>View delivery</PillButton><button onClick={() => toast("Refunds will be handled by the real payment provider later.")} className="button-base button-secondary">Refund order</button></div></section><section className="surface-panel p-5 sm:p-7"><h2 className="section-title">Customer</h2><div className="mt-5 flex items-center gap-3"><span className="grid size-11 place-items-center rounded-full bg-lilac text-[12px] font-bold text-indigo">{order.customer.name.split(" ").map((n) => n[0]).join("")}</span><div><div className="text-[14px] font-bold">{order.customer.name}</div><div className="mt-1 text-[12px] text-muted">{order.customer.email}</div></div></div><div className="mt-6 space-y-4 border-t border-line pt-5"><Info label="Phone" value={order.customer.phone || "Not provided"} /><Info label="Customer ID" value={order.customerId} /></div><h2 className="section-title mt-10">Timeline</h2><div className="mt-5 space-y-5">{["Order created", "Payment initiated", "Payment confirmed", "Product delivered"].map((item, index) => <div key={item} className="flex gap-3"><span className={`relative mt-1 grid size-5 place-items-center rounded-full ${index === 3 ? "bg-emerald-50 text-emerald-600" : "bg-lilac text-indigo"}`}>{index === 3 ? <Check size={11} /> : <span className="size-1.5 rounded-full bg-current" />}</span><div><div className="text-[12px] font-semibold">{item}</div><div className="mt-0.5 text-[11px] text-muted">{index === 0 ? formatDate(order.createdAt) : "Completed in demo flow"}</div></div></div>)}</div></section></div></AppShell>; }
function Info({ label, value }: { label: string; value: string }) { return <div><div className="text-[10px] font-bold uppercase tracking-[.1em] text-muted">{label}</div><div className="mt-1.5 text-[13px] font-semibold text-ink">{value}</div></div>; }

function Customers() { const { data } = useMoonStore(); const [query, setQuery] = useState(""); const [spend, setSpend] = useState("all"); const filtered = data.customers.filter((customer) => (!query || `${customer.name} ${customer.email} ${customer.phone}`.toLowerCase().includes(query.toLowerCase())) && (spend === "all" || spend === "buyers" && customer.orderIds.length > 0 || spend === "high" && customer.totalSpent >= 2500)); return <AppShell><PageHeader eyebrow="Relationships" title="Customers" description="People who have purchased from your storefront." /><div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="relative w-full max-w-[360px]"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search customers" className="field pl-9" /></div><select value={spend} onChange={(e) => setSpend(e.target.value)} className="field h-9 w-auto py-1.5 text-[12px]"><option value="all">All customers</option><option value="buyers">Has orders</option><option value="high">Rs. 2,500+ spent</option></select></div>{filtered.length ? <div className="surface-panel overflow-hidden"><div className="hidden grid-cols-[1.2fr_1.3fr_1fr_.7fr_.8fr] gap-4 border-b border-line bg-surface px-5 py-3 text-[10px] font-bold uppercase tracking-[.1em] text-muted md:grid"><span>Customer</span><span>Email</span><span>Phone</span><span>Orders</span><span>Total spent</span></div><div className="divide-y divide-line">{filtered.map((customer) => <Link key={customer.id} href={`/dashboard/customers/${customer.id}`} className="grid gap-2 px-5 py-4 transition hover:bg-surface md:grid-cols-[1.2fr_1.3fr_1fr_.7fr_.8fr] md:items-center md:gap-4"><div className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-full bg-lilac text-[10px] font-bold text-indigo">{customer.name.split(" ").map((n) => n[0]).join("")}</span><div><div className="text-[13px] font-semibold">{customer.name}</div><div className="text-[11px] text-muted">Last purchase {relativeDate(customer.lastPurchase)}</div></div></div><div className="text-[12px] text-slate-600">{customer.email}</div><div className="text-[12px] text-slate-600">{customer.phone}</div><div className="text-[12px] font-semibold">{customer.orderIds.length}</div><div className="text-[13px] font-bold">{formatMoney(customer.totalSpent)}</div></Link>)}</div></div> : <EmptyState icon={Users} title="No customers yet" description="Customers will appear here when someone purchases from your store." />}</AppShell>; }
function CustomerDetail() { const [, params] = useRoute("/dashboard/customers/:id"); const { data } = useMoonStore(); const customer = data.customers.find((item) => item.id === params?.id); if (!customer) return <NotFound title="Customer not found" copy="This customer is not part of the current local workspace." />; const orders = data.orders.filter((order) => order.customerId === customer.id); return <AppShell><div className="mb-7 flex items-center gap-3"><Link href="/dashboard/customers" className="icon-button"><ArrowLeft size={17} /></Link><div className="text-[12px] font-medium text-muted">Customers <ChevronRight size={12} className="mx-1 inline" /> Profile</div></div><PageHeader eyebrow="Customer profile" title={customer.name} description={customer.email} actions={<button onClick={() => toast("Customer notes are a coming soon feature.")} className="button-base button-secondary"><Pencil size={15} /> Add note</button>} /><div className="grid gap-4 lg:grid-cols-[.8fr_1.2fr]"><section className="surface-panel p-6"><span className="grid size-14 place-items-center rounded-full bg-lilac text-[15px] font-bold text-indigo">{customer.name.split(" ").map((n) => n[0]).join("")}</span><h2 className="mt-5 font-display text-[22px] font-semibold tracking-[-.04em]">{customer.name}</h2><p className="mt-2 text-[13px] text-muted">{customer.email}</p><div className="mt-7 space-y-4 border-t border-line pt-5"><Info label="Phone" value={customer.phone} /><Info label="Total spent" value={formatMoney(customer.totalSpent)} /><Info label="Orders" value={String(customer.orderIds.length)} /><Info label="Last purchase" value={formatDate(customer.lastPurchase)} /></div></section><section className="surface-panel"><div className="border-b border-line px-5 py-4"><h2 className="section-title">Purchase history</h2><p className="section-copy">Orders linked to this customer</p></div>{orders.length ? <div className="divide-y divide-line">{orders.map((order) => <Link key={order.id} href={`/dashboard/orders/${order.id}`} className="flex items-center gap-3 px-5 py-4 hover:bg-surface"><span className="grid size-9 place-items-center rounded-xl bg-lilac text-indigo"><Receipt size={15} /></span><div className="min-w-0 flex-1"><div className="text-[12px] font-bold">{order.number}</div><div className="mt-1 truncate text-[11px] text-muted">{order.items[0]?.title} · {formatDate(order.createdAt)}</div></div><div className="text-right"><div className="text-[13px] font-bold">{formatMoney(order.amount)}</div><StatusBadge status={order.status} /></div></Link>)}</div> : <div className="p-5"><EmptyState icon={Receipt} title="No purchases yet" description="Their purchase history will appear here." /></div>}</section></div></AppShell>; }

function Analytics() { const { data } = useMoonStore(); const storeViews = data.analytics.filter((e) => e.type === "store_view").length; const productViews = data.analytics.filter((e) => e.type === "product_view").length; const checkoutStarts = data.analytics.filter((e) => e.type === "checkout_started").length; const purchases = data.analytics.filter((e) => e.type === "purchase_completed").length; const revenue = data.orders.filter((o) => o.status === "paid").reduce((sum, o) => sum + o.amount, 0); const conversion = storeViews ? Math.round(purchases / storeViews * 100) : 0; const productBreakdown = data.products.map((product) => ({ ...product, views: data.analytics.filter((e) => e.type === "product_view" && e.productId === product.id).length })).filter((p) => p.views > 0 || p.sales > 0).sort((a, b) => b.views - a.views); return <AppShell><PageHeader eyebrow="Insights" title="Analytics" description="Real events from your local storefront and demo checkout." actions={<select className="field h-9 w-auto py-1.5 text-[12px]"><option>Last 30 days</option><option>All time</option></select>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><StatCard label="Store views" value={String(storeViews)} icon={Eye} accent="indigo" /><StatCard label="Product views" value={String(productViews)} icon={Package} accent="violet" /><StatCard label="Checkout starts" value={String(checkoutStarts)} icon={WalletCards} accent="orange" /><StatCard label="Orders" value={String(purchases)} icon={ShoppingBag} accent="green" /><StatCard label="Revenue" value={formatMoney(revenue)} icon={CircleDollarSign} accent="green" /><StatCard label="Conversion rate" value={`${conversion}%`} icon={TrendingUp} accent="indigo" /></div><div className="mt-4 grid gap-4 lg:grid-cols-[1.15fr_.85fr]"><section className="surface-panel p-5 sm:p-6"><h2 className="section-title">Funnel health</h2><p className="section-copy">Where attention turns into action</p><div className="mt-8 space-y-5">{[["Store views", storeViews, "bg-indigo"], ["Product views", productViews, "bg-violet-400"], ["Checkout starts", checkoutStarts, "bg-amber-400"], ["Purchases", purchases, "bg-emerald-500"]].map(([label, value, color], index, array) => <div key={label as string} className="relative"><div className="mb-2 flex items-center justify-between text-[12px]"><span className="font-semibold">{label as string}</span><span className="font-bold">{value as number}</span></div><div className="h-3 rounded-full bg-surface"><div className={`h-full rounded-full ${color}`} style={{ width: `${Math.max(Number(value) / Math.max(storeViews, 1) * 100, Number(value) ? 8 : 0)}%` }} /></div>{index < array.length - 1 && <div className="absolute -bottom-4 left-1/2 text-[10px] text-muted">↓</div>}</div>)}</div></section><section className="surface-panel p-5 sm:p-6"><h2 className="section-title">Revenue snapshot</h2><p className="section-copy">Completed paid orders in this workspace</p><div className="mt-8 flex h-[180px] items-end gap-3 border-b border-line">{data.orders.slice(0, 6).reverse().map((order) => <div key={order.id} className="flex min-w-0 flex-1 flex-col items-center gap-2"><div className="flex w-full flex-1 items-end"><div className="chart-bar w-full rounded-t-md" style={{ height: `${Math.max(order.amount / Math.max(revenue, 1) * 100, 10)}%` }} /></div><span className="max-w-full truncate text-[10px] text-muted">{order.number.slice(-4)}</span></div>)}</div><div className="mt-4 flex items-center justify-between text-[11px] text-muted"><span>Actual order data only</span><span className="font-bold text-ink">{formatMoney(revenue)}</span></div></section></div><section className="surface-panel mt-4"><div className="border-b border-line px-5 py-4"><h2 className="section-title">Product interest</h2><p className="section-copy">Views and completed sales by product</p></div>{productBreakdown.length ? <div className="divide-y divide-line">{productBreakdown.map((product) => <div key={product.id} className="flex items-center gap-3 px-5 py-4"><img src={product.cover} alt="" className="size-10 rounded-xl object-cover" /><div className="min-w-0 flex-1"><div className="truncate text-[13px] font-semibold">{product.title}</div><div className="mt-1 text-[11px] text-muted">{product.views} views</div></div><div className="text-right"><div className="text-[13px] font-bold">{product.sales}</div><div className="text-[10px] text-muted">sales</div></div></div>)}</div> : <div className="p-5"><EmptyState icon={BarChart3} title="No analytics yet" description="Share your store to start collecting insights." /></div>}</section></AppShell>; }

function Coupons() { const { data, addCoupon, updateCoupon, deleteCoupon } = useMoonStore(); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Coupon | null>(null); const [form, setForm] = useState({ code: "", type: "percentage" as "percentage" | "fixed", amount: "10", expiresAt: "2026-12-31", usageLimit: "100" }); const reset = () => { setForm({ code: "", type: "percentage", amount: "10", expiresAt: "2026-12-31", usageLimit: "100" }); setEditing(null); setOpen(false); }; const submit = (event: FormEvent) => { event.preventDefault(); if (!form.code.trim() || Number(form.amount) <= 0) { toast.error("Enter a coupon code and a positive discount."); return; } const input = { code: form.code.toUpperCase().trim(), type: form.type, amount: Number(form.amount), expiresAt: form.expiresAt, usageLimit: Number(form.usageLimit) || 1, active: true }; if (editing) updateCoupon(editing.id, input); else addCoupon(input); toast.success(editing ? "Coupon updated." : "Coupon created."); reset(); }; return <AppShell><PageHeader eyebrow="Conversion" title="Coupons" description="Create discounts that actually apply to the demo checkout." actions={<PillButton onClick={() => setOpen(true)} icon={Plus}>Create coupon</PillButton>} />{open && <div className="surface-panel mb-5 max-w-[700px] p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="section-title">{editing ? "Edit coupon" : "New coupon"}</h2><p className="section-copy">Keep it simple and useful.</p></div><button onClick={reset} className="icon-button"><X size={16} /></button></div><form onSubmit={submit} className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Code" value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="WELCOME10" /><SelectField label="Discount type" value={form.type} onChange={(value) => setForm({ ...form, type: value as "percentage" | "fixed" })}><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></SelectField><Field label={form.type === "percentage" ? "Discount %" : "Discount amount"} type="number" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} /><Field label="Expiry" type="date" value={form.expiresAt} onChange={(e) => setForm({ ...form, expiresAt: e.target.value })} /><Field label="Usage limit" type="number" min="1" value={form.usageLimit} onChange={(e) => setForm({ ...form, usageLimit: e.target.value })} /><div className="flex items-end gap-2"><button type="button" onClick={reset} className="button-base button-secondary flex-1">Cancel</button><PillButton type="submit">Save coupon</PillButton></div></form></div>}{data.coupons.length ? <div className="surface-panel overflow-hidden"><div className="hidden grid-cols-[1.1fr_.8fr_.8fr_1fr_.7fr_.6fr] gap-4 border-b border-line bg-surface px-5 py-3 text-[10px] font-bold uppercase tracking-[.1em] text-muted md:grid"><span>Code</span><span>Discount</span><span>Used</span><span>Expires</span><span>Status</span><span></span></div><div className="divide-y divide-line">{data.coupons.map((coupon) => <div key={coupon.id} className="grid gap-3 px-5 py-4 md:grid-cols-[1.1fr_.8fr_.8fr_1fr_.7fr_.6fr] md:items-center md:gap-4"><div className="font-mono text-[13px] font-bold tracking-wide">{coupon.code}</div><div className="text-[13px] font-semibold">{coupon.type === "percentage" ? `${coupon.amount}%` : formatMoney(coupon.amount)}</div><div className="text-[12px] text-muted">{coupon.used} / {coupon.usageLimit}</div><div className="text-[12px] text-muted">{formatDate(coupon.expiresAt)}</div><button onClick={() => updateCoupon(coupon.id, { active: !coupon.active })} className="text-left"><StatusBadge status={coupon.active ? "active" : "disabled"} /></button><div className="flex gap-1 md:justify-end"><button onClick={() => { setEditing(coupon); setForm({ code: coupon.code, type: coupon.type, amount: String(coupon.amount), expiresAt: coupon.expiresAt, usageLimit: String(coupon.usageLimit) }); setOpen(true); }} className="icon-button" aria-label="Edit coupon"><Pencil size={14} /></button><button onClick={() => { deleteCoupon(coupon.id); toast.success("Coupon deleted."); }} className="icon-button text-red-500" aria-label="Delete coupon"><Trash2 size={14} /></button></div></div>)}</div></div> : <EmptyState icon={Zap} title="No coupons yet" description="Create a small incentive for your next launch or returning customers." action={<PillButton onClick={() => setOpen(true)} icon={Plus}>Create coupon</PillButton>} />}</AppShell>; }

function SettingsPage() { const { data, updateCreator, updateStore, updateSettings, resetDemo, setLoggedIn } = useMoonStore(); const [saved, setSaved] = useState(false); const save = () => { setSaved(true); toast.success("Settings saved."); setTimeout(() => setSaved(false), 1600); }; return <AppShell><PageHeader eyebrow="Workspace" title="Settings" description="Keep your profile, store, and demo preferences in one place." actions={<PillButton onClick={save} icon={saved ? Check : Settings2}>{saved ? "Saved" : "Save changes"}</PillButton>} /><div className="grid gap-4 lg:grid-cols-[220px_1fr]"><aside className="hidden lg:block"><div className="sticky top-8 space-y-1">{["Profile", "Store", "Payments", "Notifications", "Account"].map((item, index) => <a href={`#${item.toLowerCase()}`} key={item} className={`settings-nav ${index === 0 ? "settings-nav-active" : ""}`}>{item}</a>)}</div></aside><div className="space-y-4"><section id="profile" className="surface-panel p-5 sm:p-7"><h2 className="section-title">Profile</h2><p className="section-copy">How you appear to customers.</p><div className="mt-6 grid gap-5 sm:grid-cols-2"><Field label="Name" value={data.creator.name} onChange={(e) => updateCreator({ name: e.target.value })} /><Field label="Email" value={data.creator.email} onChange={(e) => updateCreator({ email: e.target.value })} type="email" /></div><label className="mt-5 block"><span className="mb-2 block text-[12px] font-semibold">Bio</span><textarea className="field min-h-[100px] resize-none" value={data.creator.bio} onChange={(e) => updateCreator({ bio: e.target.value })} /></label></section><section id="store" className="surface-panel p-5 sm:p-7"><h2 className="section-title">Store</h2><p className="section-copy">Your public storefront identity.</p><div className="mt-6 grid gap-5 sm:grid-cols-2"><Field label="Store name" value={data.store.name} onChange={(e) => updateStore({ name: e.target.value })} /><Field label="Username" value={data.creator.username} onChange={(e) => updateCreator({ username: e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, "") })} /></div><label className="mt-5 block"><span className="mb-2 block text-[12px] font-semibold">Store description</span><textarea className="field min-h-[90px] resize-none" value={data.store.description} onChange={(e) => updateStore({ description: e.target.value })} /></label><div className="mt-5 rounded-xl bg-surface p-4 text-[12px] text-muted">Edit your visual style in the <Link href="/dashboard/store" className="font-semibold text-indigo">Store Builder</Link>.</div></section><section id="payments" className="surface-panel p-5 sm:p-7"><h2 className="section-title">Payments</h2><p className="section-copy">Demo payment configuration.</p><div className="mt-6 grid gap-3 sm:grid-cols-2">{["Card", "JazzCash", "Easypaisa", "Bank Transfer", "Raast"].map((item) => <div key={item} className="flex items-center gap-3 rounded-xl border border-line p-3"><span className="grid size-8 place-items-center rounded-lg bg-lilac text-indigo"><WalletCards size={15} /></span><span className="text-[12px] font-semibold">{item}</span><span className="ml-auto text-[10px] font-bold text-amber-600">Demo only</span></div>)}</div><div className="mt-5 rounded-xl bg-amber-50 p-4 text-[12px] leading-5 text-amber-800"><LockKeyhole size={15} className="mb-1" /><strong>Real payment integration will be connected later.</strong> No card details or real payments are processed in this prototype.</div></section><section id="notifications" className="surface-panel p-5 sm:p-7"><h2 className="section-title">Notifications</h2><p className="section-copy">Choose what your demo workspace keeps track of.</p><div className="mt-6 space-y-4"><ToggleRow label="Order notifications" copy="Get a reminder when a demo order is completed." checked={data.settings.orderNotifications} onChange={(checked) => { data.settings.orderNotifications = checked; save(); }} /><ToggleRow label="Email preferences" copy="Keep customer communication preferences enabled." checked={data.settings.emailPreferences} onChange={(checked) => { data.settings.emailPreferences = checked; save(); }} /></div></section><section id="account" className="surface-panel p-5 sm:p-7"><h2 className="section-title">Account</h2><p className="section-copy">Local workspace controls.</p><div className="mt-6 flex flex-wrap gap-2"><button onClick={() => { setLoggedIn(false); toast.success("Logged out of the demo workspace."); }} className="button-base button-secondary">Log out</button><button onClick={() => { resetDemo(); toast.success("Demo data reset."); }} className="button-base button-danger"><RefreshCw size={15} /> Reset demo data</button></div><p className="mt-4 text-[11px] leading-5 text-muted">Reset returns products, orders, customers, coupons, analytics, and store styling to the original demo state.</p></section></div></div></AppShell>; }
function ToggleRow({ label, copy, checked, onChange }: { label: string; copy: string; checked: boolean; onChange: (value: boolean) => void }) { return <div className="flex items-center gap-3"><div className="flex-1"><div className="text-[13px] font-semibold">{label}</div><div className="mt-1 text-[11px] text-muted">{copy}</div></div><button onClick={() => onChange(!checked)} className={`toggle ${checked ? "toggle-on" : ""}`}><span /></button></div>; }

function HelpPage() { const items = [["Getting started", "Start by customizing your profile and storefront in the Store Builder. Then add a product, publish it, and share your public link."], ["Creating products", "Products are saved locally in this prototype. Use the five-step product flow to set a title, details, included content, price, and status."], ["Customizing your store", "Add and reorder blocks, edit their settings, and switch themes. The live preview and public storefront read from the same store object."], ["Receiving payments", "Checkout uses clearly labeled demo payment methods. No real card, JazzCash, Easypaisa, bank transfer, or Raast payment is processed."], ["Managing orders", "Completed demo checkouts create connected order, payment status, customer, product sales, and analytics records."], ["Customers", "Customers are created or updated automatically when an order completes. Open a profile to see purchase history and total spend."], ["Analytics", "MoonStore tracks store views, product views, checkout starts, and completed purchases in localStorage. Empty metrics stay honest."]]; const [open, setOpen] = useState(0); return <AppShell><PageHeader eyebrow="Support" title="Help center" description="A quick guide to making the most of your MoonStore workspace." actions={<button onClick={() => toast("Support chat will be available in a future release.")} className="button-base button-secondary"><MessageCircle size={15} /> Contact support</button>} /><div className="grid gap-4 lg:grid-cols-[.7fr_1.3fr]"><section className="rounded-2xl bg-[#1a1a35] p-6 text-white"><span className="grid size-10 place-items-center rounded-xl bg-white/10 text-lilac"><BookOpen size={18} /></span><h2 className="mt-9 max-w-[250px] font-display text-[28px] font-semibold leading-[1.05] tracking-[-.05em]">Build something people want to come back to.</h2><p className="mt-4 text-[13px] leading-6 text-white/50">MoonStore is designed to keep the important things close: your work, your customers, and your next good idea.</p><Link href="/dashboard/store" className="button-base mt-8 bg-white text-ink hover:bg-lilac">Open store builder <ArrowRight size={15} /></Link></section><section className="surface-panel divide-y divide-line">{items.map(([title, copy], index) => <div key={title} className="px-5"><button onClick={() => setOpen(open === index ? -1 : index)} className="flex w-full items-center gap-3 py-5 text-left"><span className="grid size-7 place-items-center rounded-lg bg-lilac text-[10px] font-bold text-indigo">{String(index + 1).padStart(2, "0")}</span><span className="flex-1 text-[13px] font-bold">{title}</span><ChevronDown size={16} className={`text-muted transition ${open === index ? "rotate-180" : ""}`} /></button>{open === index && <div className="pb-5 pl-10 pr-5 text-[13px] leading-6 text-muted">{copy}</div>}</div>)}</section></div></AppShell>; }

function ComingSoon({ title, copy, icon: Icon }: { title: string; copy: string; icon: typeof Sparkles }) { return <AppShell><div className="flex min-h-[65vh] items-center justify-center"><div className="max-w-[560px] text-center"><span className="mx-auto grid size-14 place-items-center rounded-2xl bg-lilac text-indigo"><Icon size={24} /></span><div className="eyebrow mt-6 justify-center">Coming soon</div><h1 className="mt-4 font-display text-[42px] font-semibold leading-[1.02] tracking-[-.06em]">{title}</h1><p className="mt-4 text-[14px] leading-7 text-muted">{copy}</p><div className="mt-8 flex justify-center gap-2"><PillButton href="/dashboard" variant="secondary" icon={ArrowLeft}>Back to overview</PillButton><PillButton href="/dashboard/help" icon={BookOpen}>Read the guide</PillButton></div></div></div></AppShell>; }

function PublicStore() { const { data, track } = useMoonStore(); const [, params] = useRoute("/:username"); const username = params?.username; if (username !== data.creator.username) return <NotFound title="Store not found" copy="That creator storefront is not part of this demo." />; useEffect(() => { track({ type: "store_view" }); }, [username]); return <div className="min-h-screen" style={{ background: data.store.theme.background, color: data.store.theme.text, fontFamily: data.store.theme.font }}><div className="mx-auto flex max-w-[1000px] items-center justify-between px-5 py-5 sm:px-8"><Logo /><Link href="/" className="flex items-center gap-1.5 text-[11px] font-semibold opacity-55 hover:opacity-100">Made with moonstore <ExternalLink size={12} /></Link></div><main className="px-4 pb-16 pt-5 sm:px-8 sm:pt-10"><StorefrontContent /></main></div>; }

function ProductPage() { const { data, track } = useMoonStore(); const [, params] = useRoute("/:username/:productSlug"); const product = data.products.find((item) => item.slug === params?.productSlug && item.status === "published"); if (!product || params?.username !== data.creator.username) return <NotFound title="Product not found" copy="This product may be unpublished or the link is incorrect." />; useEffect(() => { track({ type: "product_view", productId: product.id }); }, [product.id]); return <div className="min-h-screen bg-[#fbfbfe]"><PublicTop creator={data.creator.username} /><main className="mx-auto max-w-[1080px] px-5 pb-20 pt-9 sm:px-8 lg:pt-16"><Link href={`/${data.creator.username}`} className="mb-9 inline-flex items-center gap-2 text-[12px] font-semibold text-muted hover:text-ink"><ArrowLeft size={15} /> Back to storefront</Link><div className="grid items-start gap-10 lg:grid-cols-[1.05fr_.95fr] lg:gap-16"><div className="overflow-hidden rounded-[28px] bg-surface"><img src={product.cover} alt="" className="aspect-[1.15] w-full object-cover" /></div><div className="pt-1"><div className="flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.14em] text-indigo"><span className="size-1.5 rounded-full bg-indigo" /> {PRODUCT_TYPE_LABELS[product.type]}</div><h1 className="mt-5 font-display text-[44px] font-semibold leading-[.98] tracking-[-.065em] sm:text-[62px]">{product.title}</h1><p className="mt-6 text-[15px] leading-7 text-muted">{product.description}</p><div className="mt-8 flex items-center gap-4"><span className="font-display text-[30px] font-semibold tracking-[-.05em]">{formatMoney(product.price, product.currency)}</span><span className="text-[11px] text-muted">one-time purchase</span></div><PillButton href={`/${data.creator.username}/${product.slug}/checkout`} icon={ArrowRight}>Buy now</PillButton><div className="mt-9 border-t border-line pt-6"><div className="text-[11px] font-bold uppercase tracking-[.14em] text-muted">What’s included</div><div className="mt-4 space-y-3">{product.includes.map((item) => <div key={item} className="flex items-start gap-2 text-[13px] text-slate-600"><Check size={15} className="mt-0.5 shrink-0 text-emerald-600" />{item}</div>)}</div></div><div className="mt-8 flex items-center gap-3 border-t border-line pt-6"><img src={data.creator.avatar} alt="" className="size-9 rounded-full object-cover" /><div className="text-[12px] text-muted">Created by <span className="font-semibold text-ink">{data.creator.name}</span></div></div></div></div></main></div>; }
function PublicTop({ creator }: { creator: string }) { return <header className="flex items-center justify-between border-b border-line bg-white/80 px-5 py-4 backdrop-blur-xl sm:px-8"><Logo /><Link href={`/${creator}`} className="text-[12px] font-semibold text-muted hover:text-ink">View store</Link></header>; }

function Checkout() { const { data, track, completePurchase } = useMoonStore(); const [, params] = useRoute("/:username/:productSlug/checkout"); const product = data.products.find((item) => item.slug === params?.productSlug && item.status === "published"); const [, setLocation] = useLocation(); const [form, setForm] = useState({ name: "", email: "", phone: "" }); const [method, setMethod] = useState("Card"); const [coupon, setCoupon] = useState(""); const [error, setError] = useState(""); const [processing, setProcessing] = useState(false); const couponRecord = data.coupons.find((item) => item.code.toLowerCase() === coupon.toLowerCase() && item.active && item.used < item.usageLimit); const discount = couponRecord ? couponRecord.type === "percentage" ? Math.round((product?.price ?? 0) * couponRecord.amount / 100) : Math.min(product?.price ?? 0, couponRecord.amount) : 0; useEffect(() => { if (product) track({ type: "checkout_started", productId: product.id }); }, [product?.id]); if (!product || params?.username !== data.creator.username) return <NotFound title="Product not found" copy="We couldn’t find the product you’re trying to buy." />; const submit = (event: FormEvent) => { event.preventDefault(); if (!form.name.trim() || !form.email.includes("@")) { setError("Add your name and a valid email to continue."); return; } setError(""); setProcessing(true); setTimeout(() => { const result = completePurchase({ productId: product.id, customer: form, paymentMethod: method, couponCode: couponRecord?.code }); if (result) { toast.success("Demo payment confirmed."); setLocation(`/checkout/success/${result.order.id}`); } else { setProcessing(false); toast.error("We couldn’t create the demo order."); } }, 850); }; return <div className="min-h-screen bg-[#f6f7fb]"><header className="flex items-center justify-between border-b border-line bg-white px-5 py-4 sm:px-8"><Link href={`/${data.creator.username}`} className="flex items-center gap-2 text-[12px] font-semibold text-muted"><ArrowLeft size={15} /> Back to store</Link><Logo /><span className="flex items-center gap-1.5 text-[11px] text-muted"><LockKeyhole size={13} /> Demo checkout</span></header><main className="mx-auto max-w-[980px] px-5 py-8 sm:px-8 sm:py-14"><div className="mb-8"><div className="eyebrow">Complete your purchase</div><h1 className="mt-3 font-display text-[36px] font-semibold tracking-[-.06em] sm:text-[48px]">You’re one step away.</h1><p className="mt-2 text-[13px] text-muted">This is a demo payment flow. No real payment will be processed.</p></div><form onSubmit={submit} className="grid items-start gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="surface-panel p-5 sm:p-7"><h2 className="section-title">Customer information</h2><p className="section-copy">Where should we send your access?</p><div className="mt-6 space-y-5"><Field label="Full name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Sana Rahman" /><Field label="Email address" type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="you@example.com" /><Field label="Phone (optional)" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="+92 300 1234567" /></div><div className="mt-8 border-t border-line pt-7"><h2 className="section-title">Payment method</h2><p className="section-copy">Choose a simulated payment option.</p><div className="mt-5 grid gap-2 sm:grid-cols-2">{["Card", "JazzCash", "Easypaisa", "Bank Transfer", "Raast"].map((item) => <button type="button" key={item} onClick={() => setMethod(item)} className={`payment-choice ${method === item ? "payment-choice-active" : ""}`}><span className="grid size-8 place-items-center rounded-lg bg-lilac text-indigo"><WalletCards size={15} /></span><span className="text-[12px] font-semibold">{item}</span>{method === item && <Check size={15} className="ml-auto text-indigo" />}</button>)}</div></div>{error && <p className="mt-5 rounded-xl bg-red-50 px-3 py-2.5 text-[12px] font-medium text-red-600">{error}</p>}<button disabled={processing} type="submit" className="button-base button-primary mt-7 w-full">{processing ? <><span className="spinner" /> Processing demo payment…</> : <><LockKeyhole size={15} /> Pay {formatMoney(product.price - discount)}</>}</button><p className="mt-3 text-center text-[10px] leading-5 text-muted">By continuing, you acknowledge this is a local demo and not a real transaction.</p></section><aside className="surface-panel p-5 sm:p-7"><h2 className="section-title">Order summary</h2><div className="mt-5 flex gap-3"><img src={product.cover} alt="" className="size-16 rounded-xl object-cover" /><div className="min-w-0 flex-1"><div className="text-[13px] font-bold">{product.title}</div><div className="mt-1 text-[11px] text-muted">{PRODUCT_TYPE_LABELS[product.type]}</div></div></div><div className="mt-7 space-y-3 border-t border-line pt-5 text-[13px]"><div className="flex justify-between text-muted"><span>Price</span><span>{formatMoney(product.price)}</span></div>{discount > 0 && <div className="flex justify-between text-emerald-600"><span>Discount <span className="font-mono text-[11px]">{couponRecord?.code}</span></span><span>− {formatMoney(discount)}</span></div>}<div className="flex justify-between border-t border-line pt-4 text-[15px] font-bold"><span>Total</span><span>{formatMoney(product.price - discount)}</span></div></div><div className="mt-7 border-t border-line pt-5"><label className="block"><span className="mb-2 block text-[12px] font-semibold">Have a coupon?</span><div className="flex gap-2"><input value={coupon} onChange={(e) => setCoupon(e.target.value.toUpperCase())} placeholder="WELCOME10" className="field" /><button type="button" onClick={() => couponRecord ? toast.success("Coupon applied.") : toast.error("Coupon not found or expired.")} className="button-base button-secondary">Apply</button></div></label></div><div className="mt-7 rounded-xl bg-lilac/60 p-4 text-[11px] leading-5 text-indigo-dark"><ShieldCheck size={14} className="mb-1" />You’ll receive download access immediately after this demo checkout.</div></aside></form></main></div>; }

function PurchaseSuccess() { const [, params] = useRoute("/checkout/success/:orderId"); const { data } = useMoonStore(); const order = data.orders.find((item) => item.id === params?.orderId); if (!order) return <NotFound title="Order not found" copy="We couldn’t find that purchase in this local workspace." />; const product = data.products.find((item) => item.id === order.items[0]?.productId); return <div className="flex min-h-screen items-center justify-center bg-[#fbfbfe] px-5 py-12"><div className="w-full max-w-[620px] text-center"><span className="success-check"><Check size={28} /></span><div className="eyebrow mt-7 justify-center text-emerald-600">Payment successful · Demo confirmed</div><h1 className="mt-4 font-display text-[44px] font-semibold leading-[.98] tracking-[-.065em] sm:text-[64px]">You’re all set.</h1><p className="mx-auto mt-4 max-w-[400px] text-[14px] leading-6 text-muted">Your purchase has been confirmed and your digital access is ready below.</p><div className="surface-panel mx-auto mt-9 text-left"><div className="flex items-center gap-3 border-b border-line p-5"><img src={product?.cover ?? ""} alt="" className="size-14 rounded-xl object-cover" /><div className="min-w-0 flex-1"><div className="truncate text-[14px] font-bold">{product?.title}</div><div className="mt-1 text-[11px] text-muted">Order {order.number}</div></div><div className="text-[14px] font-bold">{formatMoney(order.amount)}</div></div><div className="flex flex-col gap-3 p-5 sm:flex-row"><PillButton href={`/download/${order.id}`} icon={Download}>Download product</PillButton><PillButton href={`/${data.creator.username}`} variant="secondary">Continue shopping</PillButton></div></div><div className="mt-7 flex items-center justify-center gap-2 text-[11px] text-muted"><Check size={13} className="text-emerald-600" /> A demo order was added to the creator dashboard</div></div></div>; }

function DownloadPage() { const [, params] = useRoute("/download/:orderId"); const { data } = useMoonStore(); const order = data.orders.find((item) => item.id === params?.orderId); const product = data.products.find((item) => item.id === order?.items[0]?.productId); if (!order || !product) return <NotFound title="Download unavailable" copy="That delivery link is not available in this local workspace." />; return <div className="min-h-screen bg-[#f6f7fb]"><PublicTop creator={data.creator.username} /><main className="mx-auto max-w-[700px] px-5 py-12 sm:px-8 sm:py-20"><div className="eyebrow">Your purchase</div><h1 className="mt-4 font-display text-[42px] font-semibold tracking-[-.06em] sm:text-[58px]">Download library.</h1><p className="mt-4 text-[14px] leading-6 text-muted">Access for {order.customer.email}. These are local demo files — secure signed URLs can replace them later.</p><div className="surface-panel mt-9 overflow-hidden"><div className="flex items-center gap-3 border-b border-line p-5"><img src={product.cover} alt="" className="size-12 rounded-xl object-cover" /><div className="min-w-0 flex-1"><div className="truncate text-[14px] font-bold">{product.title}</div><div className="mt-1 text-[11px] text-muted">Purchased {formatDate(order.createdAt)}</div></div><StatusBadge status="paid" /></div><div className="divide-y divide-line">{product.files.map((file) => <div key={file.id} className="flex items-center gap-3 p-5"><span className="grid size-9 place-items-center rounded-xl bg-lilac text-indigo"><FileArchive size={16} /></span><div className="min-w-0 flex-1"><div className="truncate text-[13px] font-semibold">{file.name}</div><div className="mt-1 text-[11px] text-muted">{file.type} · {file.size}</div></div><button onClick={() => { const blob = new Blob([`MoonStore demo file: ${file.name}\n\nThis local file placeholder represents the future secure digital delivery layer.`], { type: "text/plain" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = file.name.replace(/\.[^.]+$/, "") + ".txt"; anchor.click(); URL.revokeObjectURL(url); toast.success("Demo file download started."); }} className="button-base button-secondary"><Download size={15} /> <span className="hidden sm:inline">Download</span></button></div>)}</div></div><Link href={`/${data.creator.username}`} className="mt-6 inline-flex items-center gap-2 text-[12px] font-semibold text-indigo"><ArrowLeft size={14} /> Return to storefront</Link></main></div>; }

function NotFound({ title, copy }: { title: string; copy: string }) { return <div className="flex min-h-screen items-center justify-center bg-[#fbfbfe] px-5 text-center"><div className="max-w-[500px]"><span className="mx-auto grid size-14 place-items-center rounded-2xl bg-lilac text-indigo"><Search size={23} /></span><div className="eyebrow mt-6 justify-center">404 / Not found</div><h1 className="mt-4 font-display text-[42px] font-semibold leading-[1] tracking-[-.06em]">{title}</h1><p className="mt-4 text-[14px] leading-6 text-muted">{copy}</p><div className="mt-8 flex justify-center gap-2"><PillButton href="/" variant="secondary" icon={ArrowLeft}>Back home</PillButton><PillButton href="/dashboard" icon={LayoutDashboard}>Open dashboard</PillButton></div></div></div>; }

function CalendarDays({ size = 18 }: { size?: number }) { return <span className="text-[15px]">◫</span>; }
function ArrowUpRight({ className = "" }: { className?: string }) { return <ArrowRight className={className} size={16} />; }

export default App;
